def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    # Colour 0 means blank. Painting keeps max(old, new), so a blank cell (0)
    # always takes the new colour, and a larger existing colour is kept.
    bounds = {1, n + 1}
    for op in ops:
        bounds.add(op[1])
        bounds.add(op[2] + 1)
    B = sorted(bounds)
    pos = {b: i for i, b in enumerate(B)}
    m = len(B) - 1  # number of elementary segments, each uniform across all ops

    # Lazy segment tree over elementary segments.
    # typ 1: pending "max with val"; typ 2: pending "assign val".
    typ = [1] * (4 * m)
    val = [0] * (4 * m)

    def apply(node, t, v):
        if t == 1:
            if v > val[node]:
                val[node] = v
        else:
            typ[node] = 2
            val[node] = v

    def push(node):
        left, right = 2 * node, 2 * node + 1
        apply(left, typ[node], val[node])
        apply(right, typ[node], val[node])
        typ[node] = 1
        val[node] = 0

    def update(node, lo, hi, a, b, t, v):
        if b <= lo or hi <= a:
            return
        if a <= lo and hi <= b:
            apply(node, t, v)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, a, b, t, v)
        update(2 * node + 1, mid, hi, a, b, t, v)

    for op in ops:
        a, b = pos[op[1]], pos[op[2] + 1]
        if op[0] == 1:
            update(1, 0, m, a, b, 1, op[3])
        else:
            update(1, 0, m, a, b, 2, 0)

    # Push all pending tags down to the leaves and total the cells per colour.
    totals = {}
    stack = [(1, 0, m)]
    while stack:
        node, lo, hi = stack.pop()
        if hi - lo == 1:
            c = val[node]
            if c > 0:
                totals[c] = totals.get(c, 0) + B[lo + 1] - B[lo]
            continue
        push(node)
        mid = (lo + hi) // 2
        stack.append((2 * node, lo, mid))
        stack.append((2 * node + 1, mid, hi))

    return [[c, totals[c]] for c in sorted(totals)]
